// Translator: data in translator_data.js (generated by build_site.py).
(function () {
  "use strict";
  var D = window.TRANSLATOR_DATA;
  var root = document.body.dataset.root || "";
  var selFrom = document.getElementById("from");
  var selTo = document.getElementById("to");
  var selEntry = document.getElementById("entry");
  var result = document.getElementById("result");

  // action -> [[form_id, coverage, notes], ...]
  var byAction = {};
  Object.keys(D.forms).forEach(function (fid) {
    D.forms[fid].a.forEach(function (x) {
      (byAction[x[0]] = byAction[x[0]] || []).push([fid, x[1], x[2]]);
    });
  });
  var dialect = {};
  D.dialects.forEach(function (d) { dialect[d.id] = d; });

  function el(tag, cls, text) {
    var e = document.createElement(tag);
    if (cls) e.className = cls;
    if (text != null) e.textContent = text;
    return e;
  }
  function option(sel, value, text) {
    var o = el("option", null, text);
    o.value = value;
    sel.appendChild(o);
  }
  function entryLink(eid) {
    var a = el("a", null, D.entries[eid].n);
    a.href = root + D.entries[eid].u;
    return a;
  }
  function syntax(f) {
    var p = el("pre", "syntax");
    if (f.s) p.innerHTML = f.s; else p.textContent = f.o || "(syntax not entered yet)";
    return p;
  }

  D.dialects.forEach(function (d) { option(selFrom, d.id, d.n); option(selTo, d.id, d.n); });

  function fillEntries(choice) {
    var d = dialect[selFrom.value];
    selEntry.innerHTML = "";
    d.e.forEach(function (eid) {
      if (D.entries[eid].f.some(function (f) { return D.forms[f].a.length; }))
        option(selEntry, eid, D.entries[eid].n + " (" + D.entries[eid].c.toLowerCase() + ")");
    });
    if (!selEntry.options.length) option(selEntry, "", "— no entry with actions —");
    if (choice && selEntry.querySelector('option[value="' + choice + '"]')) selEntry.value = choice;
  }

  function translate() {
    result.innerHTML = "";
    var eid = selEntry.value, to = +selTo.value;
    location.replace("#from=" + dialect[selFrom.value].c + "&entry=" + eid + "&to=" + dialect[to].c);
    if (!eid) return;
    if (+selFrom.value === to) { result.appendChild(el("p", "note", "Choose two different dialects.")); return; }
    var entry = D.entries[eid];
    var h = el("h2"); h.appendChild(entryLink(eid));
    h.appendChild(document.createTextNode(" → " + dialect[to].n));
    result.appendChild(h);

    entry.f.forEach(function (fid) {
      var f = D.forms[fid];
      if (!f.a.length) return;
      var sec = el("section", "form");
      if (f.t) sec.appendChild(el("h3", null, f.t));
      sec.appendChild(syntax(f));
      f.a.forEach(function (x) {
        var act = D.actions[x[0]];
        var box = el("div", "action");
        var p = el("p");
        var c = el("a", "action-code", act.c); c.href = root + "actions.html#" + act.c;
        p.appendChild(c);
        p.appendChild(document.createTextNode(" " + act.n));
        if (x[1] === "PARTIAL") p.appendChild(el("span", "tag", "partial"));
        if (x[2]) p.appendChild(el("small", null, " — " + x[2]));
        box.appendChild(p);
        var found = (byAction[x[0]] || []).filter(function (y) {
          var eb = D.forms[y[0]].e;
          return D.ed[eb].indexOf(to) >= 0;
        });
        if (!found.length) {
          box.appendChild(el("p", "uncovered", "No equivalent in " + dialect[to].n + "."));
        }
        found.forEach(function (y) {
          var fb = D.forms[y[0]];
          var r = el("div", "equivalent");
          var t = el("p");
          t.appendChild(entryLink(fb.e));
          if (fb.t) t.appendChild(el("small", null, " (" + fb.t + ")"));
          if (y[1] === "PARTIAL") t.appendChild(el("span", "tag", "partial"));
          if (y[2]) t.appendChild(el("small", null, " — " + y[2]));
          r.appendChild(t);
          r.appendChild(syntax(fb));
          box.appendChild(r);
        });
        sec.appendChild(box);
      });
      result.appendChild(sec);
    });
  }

  // initial state from the address (#from=...&entry=...&to=...)
  var state = {};
  location.hash.slice(1).split("&").forEach(function (kv) {
    var p = kv.split("="); if (p[0]) state[p[0]] = decodeURIComponent(p[1] || "");
  });
  function byCode(c) {
    for (var i = 0; i < D.dialects.length; i++) if (D.dialects[i].c === c) return D.dialects[i].id;
  }
  if (byCode(state.from)) selFrom.value = byCode(state.from);
  selTo.value = byCode(state.to) || (D.dialects[1] || D.dialects[0]).id;
  if (+selTo.value === +selFrom.value && D.dialects.length > 1) selTo.selectedIndex = (selFrom.selectedIndex + 1) % D.dialects.length;
  fillEntries(state.entry);

  selFrom.addEventListener("change", function () { fillEntries(); translate(); });
  selEntry.addEventListener("change", translate);
  selTo.addEventListener("change", translate);
  document.getElementById("swap").addEventListener("click", function () {
    var t = selFrom.value; selFrom.value = selTo.value; selTo.value = t; fillEntries(); translate();
  });
  translate();
})();
